public class HelpFormatter_renderWrappedText_TriageGen0Test {

    private HelpFormatter formatter;
    private StringBuffer sb;

    @Before
    public void setUp() {
        formatter = new HelpFormatter();
        sb = new StringBuffer();
    }

    @Test
    public void testRenderWrappedText_NoWrap() {
        String text = "NoWrapText";
